const est = $json.body.estudiante || {};
const ofr = $json.body.oferta || {};
const norm = (s) => String(s || "").trim().toLowerCase();
const studentSkills = Array.isArray(est.skills) ? est.skills.map((s) => String(s).trim()).filter(Boolean) : [];
const requiredSkills = Array.isArray(ofr.skills_requeridas) ? ofr.skills_requeridas.map((s) => String(s).trim()).filter(Boolean) : [];
const studentSet = new Set(studentSkills.map(norm));
const matching = requiredSkills.filter((s) => studentSet.has(norm(s)));
const missing = requiredSkills.filter((s) => !studentSet.has(norm(s)));
const total = requiredSkills.length;
const scoring = total === 0 ? 0.0 : Math.round((matching.length / total) * 100 * 100) / 100;
const scoringText = Number.isInteger(scoring) ? scoring.toFixed(1) : String(scoring);
const formula = total === 0 ? "(0 / 0) * 100 = 0.0%" : `(${matching.length} / ${total}) * 100 = ${scoringText}%`;
const estado = scoring >= 70.0 ? "Apta para entrevista" : "En desarrollo formativo";
return [{
  json: {
    estudiante_id: est.id,
    estudiante_nombre: est.nombre || "",
    estudiante_carrera: est.carrera || "",
    oferta_id: ofr.id,
    oferta_puesto: ofr.puesto || "",
    empresa: ofr.empresa || "",
    scoring,
    skills_coincidentes: matching,
    skills_faltantes: missing,
    formula,
    estado
  }
}];

